import React from 'react';
import styled from 'styled-components';

const Card = () => {
  const cardsData = [
    {
      id: 1,
      title: 'nexAR',
      description: 'Image Tracking, Multi Image Tracking, Multi Image Target, Location Based, Tap to Place',
      imageUrl: '1.png', // Replace with your image URL
    },
    {
      id: 2,
      title: 'nexNet',
      description: 'Single Page Website, Static Websites, Dynamic Websites, Responsive Design - ReactJs, Mobile App Development, Custom Application Build',
      imageUrl: '2.png', // Replace with your image URL
    },
    {
      id: 3,
      title: 'nexAi',
      description: 'Object Detection Ai',
      imageUrl: '3.png', 
    },
  ];

  return (
    <StyledWrapper>
      {cardsData.map((card) => (
        <section key={card.id} className="card">
          <img src={card.imageUrl} alt={`${card.title} icon`} className="card__icon" />
          <div className="card__content">
            <p className="card__title">{card.title}</p>
            <p className="card__description">{card.description}</p>
          </div>
        </section>
      ))}
    </StyledWrapper>
  );
}

const StyledWrapper = styled.div`
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 20px;

  section.card {
    position: relative;
    width: 350px;
    height: 200px;
    background-color: #474dc3;
    border-radius: 10px;
    display: flex;
    align-items: center;
    justify-content: center;
    overflow: hidden;
    perspective: 1000px;
    transition: all 0.8s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  }

  .card__icon {
    width: 100%;
    height: 100%;
    transition: all 0.6s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    border-radius: 10px;
    object-fit: cover;
  }

  .card:hover {
    transform: scale(1.05);
    box-shadow: 0 8px 16px #000000;
    background-color: #474dc3;
    color: #ffffff;
  }

  .card__content {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    padding: 20px;
    box-sizing: border-box;
    background-color: rgba(71, 77, 195, 0.8);
    transform: rotateX(-90deg);
    transform-origin: bottom;
    transition: all 0.6s cubic-bezier(0.175, 0.885, 0.32, 1.275);
  }

  .card:hover .card__content {
    transform: rotateX(0deg);
  }

  .card__title {
    margin: 0;
    padding-left: 5px;
    font-size: 24px;
    color: var(--white); /* Ensure --white is defined in your CSS variables */
    font-weight: 700;
  }

  .card__description {
    margin: 10px 0 0;
    font-size: 14px;
    color: #ffffff;
    line-height: 1.4;
  }

  /* Media Query for Mobile View */
  @media (max-width: 768px) {
    section.card {
      width: 100%; /* Make the card responsive */
      height: auto; /* Allow height to adjust based on content */
    }

    .card__title {
      font-size: 18px; /* Smaller font size for mobile */
    }

    .card__description {
      font-size: 12px; /* Smaller font size for mobile */
    }
  }
`;

export default Card;
